async function scanBundle(input, deliver) {
  let count = 0;
  let line = 1;
  let fragments = [];

  async function emit(text) {
    const currentLine = line++;
    if (text.trim() === "") return true;

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      const error = new Error(`Invalid JSON on line ${currentLine}`);
      error.code = "BAD_LINE";
      error.line = currentLine;
      throw error;
    }

    count++;
    return (await deliver(value, currentLine)) !== false;
  }

  async function consume(text) {
    let start = 0;
    let end;

    while ((end = text.indexOf("\n", start)) !== -1) {
      fragments.push(text.slice(start, end));
      const row = fragments.join("");
      fragments = [];

      if (!(await emit(row))) return false;
      start = end + 1;
    }

    if (start < text.length) fragments.push(text.slice(start));
    return true;
  }

  try {
    const decoder = new TextDecoder("utf-8", { ignoreBOM: true });

    while (true) {
      const chunk = await input.read();

      if (chunk === null) {
        if (!(await consume(decoder.decode()))) return count;

        if (fragments.length !== 0) {
          const row = fragments.join("");
          fragments = [];
          await emit(row);
        }

        return count;
      }

      if (!(await consume(decoder.decode(chunk, { stream: true })))) {
        return count;
      }
    }
  } finally {
    await input.close();
  }
}
